style.css:
@-moz-document domain("bestbuy.com") {
/* Best Buy Midnight Blue v1.0.3 */
html {
  background-color: #071326 !important;
}
body {
  background-color: #071326 !important;
  color: #c8e0ff !important;
}

main, [role="main"], #site-control-content, .page-wrapper,
.appContainer, .sku-list, .sku-item-list, .results-container {
  background-color: #071326 !important;
  color: #c8e0ff !important;
}

header[data-testid="header"], .shop-header, .global-header,
.header-lv-slot, .main-navigation, .utility-nav-links,
.bg-primary-emphasis, .bg-comp-surface-primary-emphasis,
[style*="background-color:#0046be"] {
  background-color: #0c2348 !important;
  color: #c8e0ff !important;
}

footer, .shop-footer, #footer, [role="contentinfo"],
.bg-default-subdued, .bg-container, .v-bg-background-gray,
.v-bg-background-light-gray, .background-gray {
  background-color: #0a1b33 !important;
  color: #c8e0ff !important;
}

/* Current storefront utility classes and older shopping components. */
.bg-default, .bg-white, .bg-comp-surface-default,
.v-bg-background-white, .v-bg-pure-white, .background-white,
.card, .sku-item, .list-item, .product-card, .product-card-container,
[data-testid="ECL-ProductCard"], .facet, .facet-list,
.facet-wrapper, .filter-panel, .fulfillment-add-to-cart-button,
.cart-item, .order-summary, .checkout-summary, .saved-items,
.saved-item, .fulfillment-fulfillment-summary,
.specifications, .review-card, .review-item, .customer-reviews,
.accordion, .accordion-body, .accordion-item, .c-accordion,
.pl-flex-carousel-container, .sugg-search-bar-input-adjust,
[role="dialog"], dialog, [role="alertdialog"], [role="menu"],
[role="listbox"], [role="tooltip"], .modal-content, .c-modal,
.c-flyout, .popover, .dropdown-menu, .sugg-search-results,
.sugg-search-results-container,
[data-testid="story-wrapper-background-view"],
[style*="background-color:#fff"],
[style*="background-color:#FFF"],
[style*="background-color: #fff"],
[style*="background-color: #FFF"],
[style*="background:#fff"],
[style*="background:#FFF"], [style*="background: #fff"],
[style*="background: #FFF"],
[style*="background-color: white"],
[style*="background-color:white"],
[style*="background: white"], [style*="background:white"],
[style*="background-color:rgb(255,255,255)"],
[style*="background-color: rgb(255, 255, 255)"],
[style*="background-color:rgba(255,255,255,1"],
[style*="background-color: rgba(255, 255, 255, 1"] {
  background-color: #102440 !important;
  color: #c8e0ff !important;
  border-color: #32537b !important;
}

[data-testid="ECL-ProductCard"]:hover, .sku-item:hover,
.review-card:hover, .cart-item:hover {
  background-color: #162e50 !important;
  box-shadow: 0 0 0 1px #32537b !important;
}

.bg-comp-track-default, [data-testid="skeleton-rectangle"] {
  background-color: #142947 !important;
}
[style*="--colorBgCompTrackDefault"] {
  background-image: linear-gradient(90deg, #142947, #21416a 50%, #142947) !important;
}
[style*="--colorBgOverlay"] {
  background-color: transparent !important;
}

.carousel-item-image-wrapper, .product-image-wrapper, .product-image,
[data-testid="ProductCard-ProductCardImageRegion-TestID"],
[data-testid="product-image"], .image-thumbnail, .image-gallery {
  background-color: #0a1b33 !important;
}

/* Keep product photos at full brightness in Best Buy's product carousels. */
[data-carousel-index] [data-testid="ProductCard-ProductCardImageRegion-TestID"],
[data-carousel-index] [data-testid="product-image"],
[data-carousel-index] [data-testid="product-image-image"],
[data-carousel-index] [data-testid="product-image-image"] img,
[data-carousel-index] [data-testid="Deals-Image-TestID-image"] img {
  filter: none !important;
  mix-blend-mode: normal !important;
  opacity: 1 !important;
}

[data-carousel-index] [data-testid="ECL-ProductCard"] [data-testid="PersonalizationImageContainer-None-TestID"],
[data-carousel-index] [data-testid="product-card"] [data-testid="product-card-image-overlay"] {
  background: transparent !important;
  opacity: 0 !important;
}

h1, h2, h3, h4, h5, h6, p, label, legend, dt, dd, th, td,
.text-default, .text-default-on-emphasis, .text-brand-tech-white,
.text-brand-tech-black, .text-white, .v-text-pure-white,
.v-text-tech-black, .body-copy, .body-copy-sm, .body-copy-lg,
.sku-title, .product-title, .priceView-customer-price,
[data-testid="price-block-customer-price"] {
  color: #c8e0ff !important;
}

small, del, s, .text-default-subdued, .text-muted, .text-secondary,
.v-text-dark-gray, .sku-model, .sku-value,
.priceView-previous-price {
  color: #9db9de !important;
}

a[href], a[href] .text-primary, a[href] .text-default,
a[href] .text-default-on-emphasis, .text-primary,
.c-button-link, .c-button-link > span {
  color: #85c4ff !important;
}

a[href]:hover, a[href]:hover .text-primary, .c-button-link:hover {
  color: #b5ddff !important;
}

input:not([type]), input[type="text"], input[type="search"],
input[type="email"], input[type="password"], input[type="tel"],
input[type="number"], input[type="url"], textarea, select,
[role="textbox"], .tb-input, .tb-input-wrapper {
  background-color: #0a1b33 !important;
  border-color: #32537b !important;
  color: #c8e0ff !important;
}

input::placeholder, textarea::placeholder {
  color: #9db9de !important;
  opacity: 1 !important;
}

button, [role="button"], input[type="button"], input[type="submit"],
.c-button, .dct-be-btn, .btn {
  color: #c8e0ff !important;
  border-color: #32537b !important;
}

.c-button-secondary, .c-button-outline, .dct-be-btn-outline,
.btn-secondary, .bg-comp-surface-default[role="button"],
button.bg-comp-surface-default, .sugg-clear-search-button,
[data-testid="save-for-later-button"] {
  background-color: #162e50 !important;
}

.c-button-primary, .c-button-availability, .btn-primary,
.add-to-cart-button, input[type="submit"], button[type="submit"],
button.bg-primary-emphasis, .c-button.bg-comp-surface-primary-emphasis,
[role="button"].bg-comp-surface-primary-emphasis {
  background-color: #1755a1 !important;
  background-image: none !important;
  border-color: #4386cf !important;
  color: #d3e8ff !important;
}

.c-button-link, button.bg-comp-surface-transparent {
  background-color: transparent !important;
}
button:hover:not(:disabled), [role="button"]:hover:not([aria-disabled="true"]),
[role="menuitem"]:hover, [role="option"]:hover, [role="tab"]:hover,
[role="option"][aria-selected="true"], [role="tab"][aria-selected="true"] {
  background-color: #2169be !important;
  color: #d3e8ff !important;
}

a[href]:focus, button:focus, input:focus,
select:focus, textarea:focus, [tabindex]:focus {
  outline: 2px solid #65b7ff !important;
  outline-offset: 2px !important;
}

button:disabled, input:disabled, [aria-disabled="true"] {
  color: #9db9de !important;
}

[data-testid="price-block-savings"], [data-testid="product-card-badge"],
.priceView-saving, .pricing-price__savings, .badge, .c-badge {
  background-color: #1b4371 !important;
  color: #a5d8ff !important;
  border-color: #32537b !important;
}

hr, table, th, td, fieldset, .border-default-subdued,
.border-comp-outline-default-muted, .v-border-gray,
.border-gray, .border-white {
  border-color: #32537b !important;
}

table, tbody tr {
  background-color: #102440 !important;
}
thead, tbody tr:nth-child(even) {
  background-color: #162e50 !important;
}

.modal-backdrop, .c-modal-overlay {
  background-color: rgba(3, 10, 22, .8) !important;
}

.fill-default, .fill-default-on-emphasis,
.icon-navigation-link-icon svg {
  fill: #c8e0ff !important;
}

::selection {
  background: #2465a7 !important;
  color: #d3e8ff !important;
}

*::-webkit-scrollbar {
  width: 11px;
  height: 11px;
}
*::-webkit-scrollbar-track, *::-webkit-scrollbar-corner {
  background: #08172c;
}
*::-webkit-scrollbar-thumb {
  background: #315c90;
  border: 2px solid #08172c;
  border-radius: 8px;
}
*::-webkit-scrollbar-thumb:hover {
  background: #4b85c0;
}
}
